module.exports = "<!DOCTYPE html>\n<html lang=\"en-GB\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Compare Research Peptides — Velox Peptides</title>\n<meta name=\"description\" content=\"Compare research peptides side by side — mechanism, receptor targets, research data, molecular weight, solubility and pricing. Compare up to 5 at once. For in vitro research use only.\">\n<link rel=\"canonical\" href=\"https://veloxpeps.com/tools/compare/\">\n<meta property=\"og:title\" content=\"Compare Research Peptides — Velox Peptides\">\n<meta property=\"og:description\" content=\"Side-by-side comparison of research peptides — mechanism, receptors, research data, molecular weight, solubility and pricing.\">\n<meta property=\"og:type\" content=\"website\">\n<meta property=\"og:url\" content=\"https://veloxpeps.com/tools/compare/\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@700;800;900&family=DM+Mono:wght@400;500&family=Inter:wght@400;500;600;700;800;900&family=Space+Grotesk:wght@600;700;800&display=swap\">\n<link rel=\"stylesheet\" href=\"/assets/css/core.css\">\n<style>\n  :root{ --g:#01D3A0; --bg:#04070b; --bg2:#0a0e13; --bg3:#0e141b; --brd:#1a2230; --mut:#8aa0a0; --dim:#4b5563; --win:rgba(1,211,160,.12); }\n  *{box-sizing:border-box;}\n  body{margin:0;background:var(--bg);color:#fff;font-family:Inter,system-ui,sans-serif;}\n  .cmp-wrap{max-width:1180px;margin:0 auto;padding:22px 18px 90px;}\n\n  /* tightened header */\n  .cmp-head{display:flex;flex-wrap:wrap;align-items:baseline;gap:6px 14px;}\n  .cmp-head h1{font-family:'Barlow Condensed',sans-serif;font-weight:900;text-transform:uppercase;font-size:clamp(26px,4vw,38px);line-height:.95;margin:0;}\n  .cmp-head h1 .ac{color:var(--g);}\n  .cmp-head p{color:var(--mut);font-size:14px;margin:0;}\n  .cmp-head .legal{font-family:'DM Mono',monospace;font-size:10.5px;color:var(--dim);width:100%;margin:3px 0 0;}\n\n  /* compact action toolbar */\n  .cmp-bar{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:14px 0 10px;}\n  .cmp-btn{font-family:Inter,sans-serif;font-weight:700;font-size:12.5px;border-radius:9px;padding:8px 13px;cursor:pointer;border:1px solid var(--brd);background:var(--bg3);color:#cdd6dd;transition:.15s;text-decoration:none;display:inline-flex;align-items:center;gap:6px;white-space:nowrap;}\n  .cmp-btn:hover{border-color:var(--g);color:#fff;}\n  .cmp-btn.primary{background:var(--g);color:#04140f;border-color:var(--g);}\n  .cmp-btn.sm{font-size:12px;padding:7px 11px;}\n  #addSlot{margin-left:auto;}\n  .cmp-maxnote{font-family:'DM Mono',monospace;font-size:11px;color:var(--dim);}\n\n  /* lens bar — moved up, always visible */\n  .cmp-lenses{display:flex;gap:6px;overflow-x:auto;padding:2px 0 12px;border-bottom:1px solid var(--brd);}\n  .cmp-lens{flex:0 0 auto;background:var(--bg3);border:1px solid var(--brd);cursor:pointer;color:var(--mut);font-family:Inter,sans-serif;font-weight:600;font-size:12.5px;padding:7px 13px;border-radius:999px;display:inline-flex;align-items:center;gap:6px;transition:.15s;}\n  .cmp-lens .ic{font-size:14px;}\n  .cmp-lens.on{background:#fff;color:#04140f;border-color:#fff;}\n  .cmp-lens:not(.on):hover{color:#fff;border-color:var(--g);}\n\n  /* comparison matrix */\n  .cmp-matrix-wrap{overflow-x:auto;margin-top:14px;-webkit-overflow-scrolling:touch;border:1px solid var(--brd);border-radius:16px;}\n  .cmp-matrix{display:grid;width:100%;}\n  .mx-cell{padding:13px 14px;border-bottom:1px solid var(--brd);min-width:0;font-size:13.5px;line-height:1.5;color:#dfe6ea;}\n  .mx-label{position:sticky;left:0;z-index:2;background:var(--bg2);font-family:'DM Mono',monospace;font-size:10.5px;letter-spacing:.05em;text-transform:uppercase;color:var(--mut);display:flex;align-items:center;border-right:1px solid var(--brd);}\n  .mx-row-odd .mx-cell{background:var(--bg2);}\n  .mx-row-odd .mx-label{background:#0c1117;}\n  .mx-val.win{background:var(--win);}\n  .mx-val .wc{display:inline-block;color:var(--g);font-weight:800;font-size:11px;margin-left:6px;white-space:nowrap;}\n\n  /* compound header cells */\n  .mx-head{padding:14px;border-bottom:2px solid var(--brd);position:relative;background:var(--bg);}\n  .mx-head.mx-label{background:var(--bg2);}\n  .mx-avatar{width:42px;height:42px;border-radius:11px;display:flex;align-items:center;justify-content:center;font-family:'Barlow Condensed',sans-serif;font-weight:900;font-size:21px;border:1px solid var(--brd);margin-bottom:9px;}\n  .mx-name{font-family:'Space Grotesk','Inter',sans-serif;font-weight:800;font-size:15.5px;line-height:1.12;color:#fff;}\n  .mx-aka{font-size:10.5px;color:var(--mut);margin-top:3px;line-height:1.3;}\n  .mx-pill{display:inline-block;font-family:'DM Mono',monospace;font-size:9px;letter-spacing:.04em;text-transform:uppercase;padding:3px 8px;border-radius:999px;}\n  .mx-rm{position:absolute;top:8px;right:8px;width:22px;height:22px;border-radius:50%;border:1px solid var(--brd);background:var(--bg3);color:var(--mut);cursor:pointer;font-size:13px;line-height:1;display:flex;align-items:center;justify-content:center;}\n  .mx-rm:hover{border-color:#f0637e;color:#f0637e;}\n\n  /* pricing cells */\n  .mx-price{font-family:'Barlow Condensed',sans-serif;font-weight:900;font-size:27px;color:var(--g);line-height:1;display:flex;align-items:center;flex-wrap:wrap;gap:8px;}\n  .mx-best{font-family:'DM Mono',monospace;font-size:9px;letter-spacing:.04em;text-transform:uppercase;color:#04140f;background:var(--g);border-radius:999px;padding:3px 8px;}\n  .mx-buy{display:inline-block;margin-top:10px;background:var(--g);color:#04140f;font-weight:800;font-size:12.5px;padding:8px 14px;border-radius:8px;text-decoration:none;}\n  .mx-buy:hover{filter:brightness(1.07);}\n  .mx-commission{display:flex;flex-direction:column;align-items:flex-start;gap:7px;}\n  .mx-commission .lbl{font-size:12px;color:var(--mut);}\n  .mx-cbtn{display:inline-flex;align-items:center;gap:5px;font-size:11.5px;font-weight:700;padding:7px 11px;border-radius:8px;text-decoration:none;border:1px solid var(--brd);background:var(--bg3);color:#cdd6dd;transition:.15s;}\n  .mx-cbtn.alt{border-color:rgba(1,211,160,.45);color:var(--g);}\n  .mx-cbtn:hover{border-color:var(--g);color:#fff;}\n\n  /* picker overlay */\n  .cmp-picker{position:fixed;inset:0;z-index:120;background:rgba(3,5,8,.7);display:none;align-items:flex-start;justify-content:center;padding:40px 16px;overflow-y:auto;}\n  .cmp-picker.open{display:flex;}\n  .cmp-picker-box{background:var(--bg2);border:1px solid var(--brd);border-radius:18px;max-width:680px;width:100%;padding:20px;}\n  .cmp-picker-box h3{font-family:'Barlow Condensed',sans-serif;font-weight:800;text-transform:uppercase;font-size:22px;margin:0 0 12px;}\n  .cmp-search{width:100%;background:#05070a;border:1px solid var(--brd);border-radius:10px;color:#fff;font-size:15px;padding:12px 14px;outline:none;margin-bottom:14px;}\n  .cmp-search:focus{border-color:var(--g);}\n  .cmp-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:8px;}\n  .cmp-pick{display:flex;gap:10px;align-items:center;background:var(--bg3);border:1px solid var(--brd);border-radius:12px;padding:10px;cursor:pointer;text-align:left;transition:.13s;color:#eef3f2;}\n  .cmp-pick:hover{border-color:var(--g);}\n  .cmp-pick .pt{width:38px;height:38px;border-radius:9px;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-family:'Barlow Condensed',sans-serif;font-weight:900;font-size:18px;border:1px solid var(--brd);}\n  .cmp-pick .pn{font-weight:700;font-size:13.5px;line-height:1.1;color:#fff;}\n  .cmp-pick .pa{font-size:10.5px;color:var(--mut);}\n  .cmp-picker-close{float:right;background:none;border:none;color:var(--mut);font-size:22px;cursor:pointer;line-height:1;}\n\n  .toastc{position:fixed;bottom:32px;left:50%;transform:translateX(-50%);background:#fff;color:#04140f;font-weight:700;font-size:13px;padding:10px 18px;border-radius:999px;z-index:200;opacity:0;transition:opacity .2s;pointer-events:none;}\n  .toastc.show{opacity:1;}\n  .cmp-acct{position:fixed;left:50%;transform:translateX(-50%);bottom:28px;z-index:80;display:none;align-items:center;gap:12px;background:var(--bg2);border:1px solid rgba(1,211,160,.35);border-radius:12px;padding:11px 14px;max-width:92vw;box-shadow:0 12px 40px rgba(0,0,0,.5);}\n  .cmp-acct.show{display:flex;}\n  .cmp-acct span{font-size:13px;color:#cdd6dd;}\n  .cmp-acct a{background:var(--g);color:#04140f;font-weight:800;font-size:12.5px;padding:7px 13px;border-radius:8px;text-decoration:none;white-space:nowrap;}\n  .cmp-acct button{background:none;border:none;color:var(--mut);font-size:18px;cursor:pointer;line-height:1;}\n\n  /* phones */\n  @media(max-width:600px){\n    .cmp-wrap{padding:16px 12px 84px;}\n    .cmp-head .legal{font-size:10px;}\n    .cmp-bar{gap:6px;margin:12px 0 8px;}\n    #addSlot{margin-left:0;}\n    .cmp-btn{font-size:12px;padding:8px 11px;}\n    .cmp-btn .lbl-full{display:none;}\n    .cmp-grid{grid-template-columns:1fr 1fr;}\n    .mx-price{font-size:23px;}\n    .cmp-picker{padding:24px 10px;}\n    .cmp-acct{flex-wrap:wrap;justify-content:center;text-align:center;gap:8px;padding:11px 12px;}\n  }\n</style>\n</head>\n<body>\n<header class=\"site-header\"><nav class=\"nav\" aria-label=\"Primary\">\n  <a class=\"nav-logo\" href=\"/\" aria-label=\"Velox Peptides\"><img class=\"nav-logo-img\" src=\"/assets/images/veloxpeps2.png\" alt=\"Velox Peptides\" width=\"150\" height=\"auto\"></a>\n  <div class=\"nav-links\">\n    <a class=\"nl\" href=\"/compounds/\">Shop</a>\n    <div class=\"nl-drop\"><a class=\"nl nl-drop-btn active\" href=\"/design-lab/\">Tools <span class=\"nl-caret\">&#9662;</span></a><div class=\"nl-menu\"><a class=\"nl-item\" href=\"/design-lab/\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 3c.4 4 2.6 6.2 6.6 6.6C14.6 10 12.4 12.2 12 16.2 11.6 12.2 9.4 10 5.4 9.6 9.4 9.2 11.6 7 12 3Z\"/></svg>Design Lab</a><a class=\"nl-item\" href=\"/tools/compare/\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 3v17M6 21h12M12 6 5 8l3 5a3 3 0 0 1-6 0l3-5M12 6l7 2-3 5a3 3 0 0 0 6 0l-3-5\"/></svg>Compare peptides</a><a class=\"nl-item\" href=\"/tools/scheduler/\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"3.5\" y=\"5\" width=\"17\" height=\"15.5\" rx=\"2.5\"/><path d=\"M3.5 9.5h17M8 3v4M16 3v4\"/></svg>Protocol Scheduler</a></div></div>\n\n    <a class=\"nl\" href=\"/pro/\" style=\"color:#01D3A0;font-weight:700\">Pro</a>\n  </div>\n</nav></header>\n\n<main class=\"cmp-wrap\">\n  <div class=\"cmp-head\">\n    <h1>Compare <span class=\"ac\">peptides.</span></h1>\n    <p>Pick up to five. Compare side by side.</p>\n    <p class=\"legal\">For in vitro research use only. Research-framed summaries; not medical advice.</p>\n  </div>\n\n  <div class=\"cmp-bar\">\n    <button class=\"cmp-btn primary sm\" id=\"shareBtn\">🔗 Share</button>\n    <button class=\"cmp-btn sm\" id=\"stackBtn\">🃏 Stack card</button>\n    <button class=\"cmp-btn sm\" id=\"resetBtn\">↺ Reset</button>\n    <a class=\"cmp-btn sm\" href=\"/design-lab/\">✦ Design new →</a>\n    <span id=\"addSlot\"></span>\n  </div>\n\n  <div class=\"cmp-lenses\" id=\"lenses\" role=\"tablist\" aria-label=\"Comparison lens\"></div>\n\n  <div class=\"cmp-matrix-wrap\"><div class=\"cmp-matrix\" id=\"matrix\"></div></div>\n</main>\n\n<!-- add-peptide picker -->\n<div class=\"cmp-picker\" id=\"picker\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Add a peptide\">\n  <div class=\"cmp-picker-box\">\n    <button class=\"cmp-picker-close\" id=\"pickerClose\" aria-label=\"Close\">×</button>\n    <h3>Add a peptide</h3>\n    <input class=\"cmp-search\" id=\"pickerSearch\" type=\"search\" placeholder=\"Search peptides…\" autocomplete=\"off\">\n    <div class=\"cmp-grid\" id=\"pickerGrid\"></div>\n  </div>\n</div>\n<!-- Build-Your-Stack card overlay -->\n<div class=\"cmp-picker\" id=\"stack\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Your research stack card\">\n  <div class=\"cmp-picker-box\" style=\"max-width:560px;text-align:center\">\n    <button class=\"cmp-picker-close\" id=\"stackClose\" aria-label=\"Close\">×</button>\n    <h3 style=\"text-align:left\">Your research stack</h3>\n    <canvas id=\"stackCanvas\" width=\"1080\" height=\"1350\" style=\"width:100%;max-width:380px;border-radius:14px;border:1px solid var(--brd);background:#04070b\"></canvas>\n    <div style=\"display:flex;gap:10px;flex-wrap:wrap;justify-content:center;margin-top:14px\">\n      <button class=\"cmp-btn primary\" id=\"stackDl\">⬇ Download image</button>\n      <button class=\"cmp-btn\" id=\"stackShare\">⇪ Share</button>\n    </div>\n  </div>\n</div>\n<div class=\"cmp-acct\" id=\"acctNudge\"><span>Enjoying this? Create a free account to save &amp; build more comparisons.</span><a href=\"/account/?next=/tools/compare/\">Create free account</a><button id=\"acctClose\" aria-label=\"Dismiss\">×</button></div>\n<div class=\"toastc\" id=\"toastc\"></div>\n\n<script src=\"/assets/js/peptide-data.js\"></script>\n<script>\n(function(){\n  var ALL = window.VELOX_PEPTIDES || [];\n  var BY = window.VELOX_PEPTIDE_BY_ID || {};\n  var MAX = 5;\n  var TABS = [\n    {k:'overview', label:'Overview', ic:'🔬'},\n    {k:'mechanism', label:'Mechanism', ic:'⚙️'},\n    {k:'receptors', label:'Receptors', ic:'🎯'},\n    {k:'research', label:'Research', ic:'📊'},\n    {k:'properties', label:'Properties', ic:'⚗️'},\n    {k:'pricing', label:'Pricing', ic:'£'},\n  ];\n  var LABELS = {category:'Category', mw:'Molecular weight', solubility:'Solubility', mechanism:'Mechanism', receptors:'Receptor targets', research:'Research focus', summary:'Summary', price:'Price', availability:'Availability'};\n  var LENS_ROWS = {\n    overview:   ['category','mw','solubility','mechanism','receptors','research','price'],\n    mechanism:  ['summary','mechanism'],\n    receptors:  ['receptors'],\n    research:   ['research'],\n    properties: ['mw','solubility','category'],\n    pricing:    ['price','availability'],\n  };\n  var $=function(id){return document.getElementById(id);};\n  function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}\n  function fmt(v){return v%1===0?v:v.toFixed(2);}\n\n  // ── state from URL ──\n  var params = new URLSearchParams(location.search);\n  var ids = (params.get('ids')||'').split(',').map(function(x){return x.trim();}).filter(function(x){return BY[x];});\n  if(!ids.length){\n    var m = location.pathname.match(/\\/compare\\/([^/]+)/);\n    if(m) ids = m[1].split('-vs-').map(function(x){return x.trim();}).filter(function(x){return BY[x];});\n  }\n  if(!ids.length) ids = ['bpc-157','tb-500'];\n  ids = ids.slice(0,MAX);\n  var tab = params.get('tab'); if(!TABS.some(function(t){return t.k===tab;})) tab='overview';\n\n  function syncURL(){\n    var u = new URL(location.href);\n    u.searchParams.set('ids', ids.join(','));\n    u.searchParams.set('tab', tab);\n    history.replaceState(null,'',u);\n    var names = ids.map(function(id){return (BY[id]||{}).name||id;});\n    document.title = (names.length>1 ? names.join(' vs ')+' — Side-by-Side Comparison' : 'Compare Research Peptides') + ' — Velox Peptides';\n  }\n\n  function avatar(p, cls){\n    return '<div class=\"'+cls+'\" style=\"color:'+p.catColor+';background:'+p.catColor+'14;border-color:'+p.catColor+'33\">'+esc(p.name.charAt(0))+'</div>';\n  }\n\n  // ── winner logic (only objective attributes) ──\n  function solScore(s){ s=(s||'').toLowerCase(); if(s.indexOf('highly')!==-1) return 3; if(s.indexOf('water-sol')!==-1||s.indexOf('water sol')!==-1||s.indexOf('freely')!==-1) return 2; if(s.indexOf('soluble')!==-1) return 1; return 0; }\n  function winners(attr, list){\n    if(list.length<2) return null;\n    if(attr==='mw'){\n      var nums=list.filter(function(p){return typeof p.mw==='number';}).map(function(p){return p.mw;});\n      if(nums.length<2) return null; var mn=Math.min.apply(null,nums);\n      if(nums.every(function(v){return v===mn;})) return null;\n      var w={}; list.forEach(function(p){ if(p.mw===mn) w[p.id]=true; }); return w;\n    }\n    if(attr==='solubility'){\n      var sc=list.map(function(p){return solScore(p.solubility);}); var mx=Math.max.apply(null,sc);\n      if(mx===0 || sc.filter(function(v){return v===mx;}).length===list.length) return null;\n      var w={}; list.forEach(function(p){ if(solScore(p.solubility)===mx) w[p.id]=true; }); return w;\n    }\n    if(attr==='price'){\n      var ins=list.filter(function(p){return p.buyUrl;}); if(ins.length<2) return null;\n      var mnp=Math.min.apply(null,ins.map(function(p){return p.price;}));\n      if(ins.every(function(p){return p.price===mnp;})) return null;\n      var w={}; ins.forEach(function(p){ if(p.price===mnp) w[p.id]=true; }); return w;\n    }\n    return null;\n  }\n\n  function cell(attr, p, isWin){\n    if(attr==='category') return '<span class=\"mx-pill\" style=\"background:'+p.catColor+'22;color:'+p.catColor+'\">'+esc(p.catLabel)+'</span>';\n    if(attr==='mw') return (typeof p.mw==='number' ? esc(p.mw)+' g/mol' : '—') + (isWin?'<span class=\"wc\">✓ lowest</span>':'');\n    if(attr==='solubility') return esc(p.solubility) + (isWin?'<span class=\"wc\">✓ best</span>':'');\n    if(attr==='mechanism') return esc(p.mechanism);\n    if(attr==='receptors') return esc(p.receptors);\n    if(attr==='research') return esc(p.research);\n    if(attr==='summary') return esc(p.blurb);\n    if(attr==='availability') return p.buyUrl ? '<span style=\"color:var(--g);font-weight:600\">In stock at Velox</span>' : '<span style=\"color:var(--mut)\">Not stocked — commission only</span>';\n    if(attr==='price'){\n      if(p.buyUrl) return '<div class=\"mx-price\">£'+fmt(p.price)+(isWin?'<span class=\"mx-best\">Best value</span>':'')+'</div>'+\n        '<a class=\"mx-buy\" href=\"'+p.buyUrl+'\">Order '+esc(p.name)+' →</a>';\n      return '<div class=\"mx-commission\"><span class=\"lbl\">Not stocked at Velox yet</span>'+\n        '<a class=\"mx-cbtn\" href=\"/design-lab/order/?name='+encodeURIComponent(p.name)+'\">⚗ Commission synthesis</a>'+\n        '<a class=\"mx-cbtn alt\" href=\"/design-lab/\">✦ Design alternative</a></div>';\n    }\n    return '';\n  }\n\n  function renderMatrix(){\n    var list = ids.map(function(id){return BY[id];}).filter(Boolean);\n    var n = list.length;\n    var mx = $('matrix');\n    mx.style.gridTemplateColumns = 'minmax(116px,150px) repeat('+n+',minmax(150px,1fr))';\n    var html = '';\n    // header row: empty top-left + compound columns\n    html += '<div class=\"mx-cell mx-label mx-head\"></div>';\n    list.forEach(function(p){\n      html += '<div class=\"mx-cell mx-head\">'+\n        (n>1?'<button class=\"mx-rm\" data-rm=\"'+p.id+'\" aria-label=\"Remove '+esc(p.name)+'\">×</button>':'')+\n        avatar(p,'mx-avatar')+\n        '<div class=\"mx-name\">'+esc(p.name)+'</div>'+\n        (p.aka?'<div class=\"mx-aka\">'+esc(p.aka)+'</div>':'')+\n        '<div style=\"margin-top:7px\"><span class=\"mx-pill\" style=\"background:'+p.catColor+'22;color:'+p.catColor+'\">'+esc(p.catLabel)+'</span></div>'+\n      '</div>';\n    });\n    // attribute rows\n    var rows = LENS_ROWS[tab] || LENS_ROWS.overview;\n    rows.forEach(function(attr, ri){\n      var w = winners(attr, list);\n      var rc = (ri%2===1) ? ' mx-row-odd' : '';\n      html += '<div class=\"mx-cell mx-label'+rc+'\">'+esc(LABELS[attr]||attr)+'</div>';\n      list.forEach(function(p){\n        var isWin = !!(w && w[p.id]);\n        html += '<div class=\"mx-cell mx-val'+rc+(isWin?' win':'')+'\">'+cell(attr,p,isWin)+'</div>';\n      });\n    });\n    mx.innerHTML = html;\n    mx.querySelectorAll('[data-rm]').forEach(function(b){ b.addEventListener('click',function(){ remove(b.getAttribute('data-rm')); }); });\n    renderAddSlot();\n  }\n\n  function renderAddSlot(){\n    var slot = $('addSlot');\n    if(ids.length < MAX){\n      slot.innerHTML = '<button class=\"cmp-btn sm\" id=\"addBtn\">+ Add peptide ('+ids.length+'/'+MAX+')</button>';\n      $('addBtn').addEventListener('click', openPicker);\n    } else {\n      slot.innerHTML = '<span class=\"cmp-maxnote\">Max '+MAX+' reached</span>';\n    }\n  }\n\n  function renderLenses(){\n    $('lenses').innerHTML = TABS.map(function(t){\n      return '<button class=\"cmp-lens'+(t.k===tab?' on':'')+'\" data-tab=\"'+t.k+'\" role=\"tab\" aria-selected=\"'+(t.k===tab)+'\"><span class=\"ic\">'+t.ic+'</span>'+esc(t.label)+'</button>';\n    }).join('');\n    $('lenses').querySelectorAll('[data-tab]').forEach(function(b){ b.addEventListener('click',function(){ tab=b.getAttribute('data-tab'); renderLenses(); renderMatrix(); syncURL(); }); });\n  }\n\n  function remove(id){ ids = ids.filter(function(x){return x!==id;}); renderMatrix(); syncURL(); }\n  function add(id){ if(ids.indexOf(id)===-1 && ids.length<MAX){ ids.push(id); renderMatrix(); syncURL(); } closePicker(); accountGate(); }\n\n  // ── Account nudge: viewing is always free; after the first interactive build,\n  // prompt non-signed-in visitors to create a free account. Non-blocking. ──\n  function isSignedIn(){ try{ for(var i=0;i<localStorage.length;i++){ var k=localStorage.key(i); if(k&&k.indexOf(\"sb-\")===0&&k.indexOf(\"-auth-token\")!==-1&&localStorage.getItem(k)) return true; } }catch(e){} return false; }\n  function accountGate(){\n    if(isSignedIn()) return;\n    var uses=0; try{ uses=+localStorage.getItem(\"vlx_cmp_uses\")||0; localStorage.setItem(\"vlx_cmp_uses\",uses+1); }catch(e){}\n    if(uses>=1 && !sessionStorage.getItem(\"vlx_cmp_nudged\")){\n      try{ sessionStorage.setItem(\"vlx_cmp_nudged\",\"1\"); }catch(e){}\n      $('acctNudge').classList.add('show');\n    }\n  }\n\n  // ── picker ──\n  function renderPicker(q){\n    q=(q||'').toLowerCase();\n    var avail = ALL.filter(function(p){ return ids.indexOf(p.id)===-1 && (!q || (p.name+' '+(p.aka||'')+' '+p.catLabel).toLowerCase().indexOf(q)!==-1); });\n    $('pickerGrid').innerHTML = avail.map(function(p){\n      return '<button class=\"cmp-pick\" data-add=\"'+p.id+'\">'+avatar(p,'pt')+\n        '<div><div class=\"pn\">'+esc(p.name)+'</div><div class=\"pa\">'+esc(p.aka||p.catLabel)+'</div></div></button>';\n    }).join('') || '<div style=\"color:var(--mut);font-size:14px;padding:8px\">No matches.</div>';\n    $('pickerGrid').querySelectorAll('[data-add]').forEach(function(b){ b.addEventListener('click',function(){ add(b.getAttribute('data-add')); }); });\n  }\n  function openPicker(){ if(ids.length>=MAX) return; $('pickerSearch').value=''; renderPicker(''); $('picker').classList.add('open'); setTimeout(function(){$('pickerSearch').focus();},50); }\n  function closePicker(){ $('picker').classList.remove('open'); }\n\n  function toast(t){ var el=$('toastc'); el.textContent=t; el.classList.add('show'); setTimeout(function(){el.classList.remove('show');},1600); }\n\n  $('pickerClose').addEventListener('click', closePicker);\n  $('picker').addEventListener('click', function(e){ if(e.target===$('picker')) closePicker(); });\n  $('pickerSearch').addEventListener('input', function(){ renderPicker(this.value); });\n\n  // ── Build-Your-Stack card ──\n  function synergyNote(list){\n    var idset = list.map(function(p){return p.id;});\n    var has=function(id){return idset.indexOf(id)!==-1;};\n    if(has('bpc-157')&&has('tb-500')) return 'BPC-157 + TB-500: complementary tissue-repair pathways (angiogenesis + cell migration).';\n    var ghrh=idset.some(function(id){return ['cjc-1295','sermorelin','tesamorelin'].indexOf(id)!==-1;});\n    var ghrp=idset.some(function(id){return ['ipamorelin','ghrp-2','ghrp-6','hexarelin'].indexOf(id)!==-1;});\n    if(ghrh&&ghrp) return 'GHRH + ghrelin-receptor agonists are studied together for amplified GH release.';\n    var cats=[]; list.forEach(function(p){ if(cats.indexOf(p.catLabel)===-1) cats.push(p.catLabel); });\n    if(cats.length===1) return 'All compounds sit in one research area — ' + cats[0] + '.';\n    return 'Selected for complementary research across ' + cats.length + ' areas.';\n  }\n  function drawStack(){\n    var list = ids.map(function(id){return BY[id];}).filter(Boolean);\n    var c = $('stackCanvas'), x = c.getContext('2d'), W=1080, H=1350;\n    x.fillStyle='#04070b'; x.fillRect(0,0,W,H);\n    var grd=x.createLinearGradient(0,0,W,0); grd.addColorStop(0,'#01D3A0'); grd.addColorStop(1,'#6cf7d6');\n    x.fillStyle=grd; x.fillRect(0,0,W,12);\n    x.fillStyle='#fff'; x.font='900 54px \"Barlow Condensed\", Arial'; x.textBaseline='alphabetic';\n    x.fillText('VELOX', 70, 110); x.fillStyle='#01D3A0'; x.fillText(' PEPTIDES', 70+x.measureText('VELOX').width, 110);\n    x.fillStyle='#8aa0a0'; x.font='500 24px \"DM Mono\", monospace'; x.fillText('RESEARCH STACK', 72, 150);\n    var y=230, total=0, nostock=0;\n    list.forEach(function(p){\n      x.fillStyle='#0e141b'; roundRect(x,70,y,W-140,150,18); x.fill();\n      x.fillStyle=p.catColor; x.beginPath(); x.arc(150,y+75,46,0,7); x.fill();\n      x.fillStyle='#04140f'; x.font='900 44px \"Barlow Condensed\", Arial'; x.textAlign='center'; x.fillText(p.name.charAt(0),150,y+92); x.textAlign='left';\n      x.fillStyle='#fff'; x.font='800 40px Inter, Arial'; x.fillText(p.name, 226, y+62);\n      x.fillStyle=p.catColor; x.font='500 22px \"DM Mono\", monospace'; x.fillText(p.catLabel.toUpperCase(), 226, y+100);\n      x.textAlign='right';\n      if(p.buyUrl){ total+=p.price; x.fillStyle='#01D3A0'; x.font='900 46px \"Barlow Condensed\", Arial'; x.fillText('£'+(p.price%1===0?p.price:p.price.toFixed(2)), W-92, y+92); }\n      else { nostock++; x.fillStyle='#8aa0a0'; x.font='500 22px \"DM Mono\", monospace'; x.fillText('commission', W-92, y+88); }\n      x.textAlign='left';\n      y+=168;\n    });\n    y+=10; x.strokeStyle='#1a2230'; x.beginPath(); x.moveTo(70,y); x.lineTo(W-70,y); x.stroke(); y+=66;\n    x.fillStyle='#8aa0a0'; x.font='600 30px Inter, Arial'; x.fillText('Total (in-stock)', 72, y);\n    x.fillStyle='#fff'; x.font='900 56px \"Barlow Condensed\", Arial'; x.textAlign='right';\n    x.fillText('£'+(Math.round(total*100)/100), W-92, y+8); x.textAlign='left';\n    if(nostock){ y+=42; x.fillStyle='#7b8cff'; x.font='500 22px \"DM Mono\", monospace'; x.fillText('+ '+nostock+' to commission via Design Lab', 72, y); }\n    y+=74; x.fillStyle='#01D3A0'; x.font='500 22px \"DM Mono\", monospace'; x.fillText('✦ SYNERGY', 72, y); y+=42;\n    x.fillStyle='#cdd6dd'; x.font='400 30px Inter, Arial'; wrapText(x, synergyNote(list), 72, y, W-150, 40);\n    x.fillStyle='#4b5563'; x.font='500 24px \"DM Mono\", monospace';\n    x.fillText('veloxpeps.com/tools/compare', 72, H-90);\n    x.fillText('For in vitro research use only.', 72, H-52);\n  }\n  function roundRect(x,rx,ry,w,h,r){ x.beginPath(); x.moveTo(rx+r,ry); x.arcTo(rx+w,ry,rx+w,ry+h,r); x.arcTo(rx+w,ry+h,rx,ry+h,r); x.arcTo(rx,ry+h,rx,ry,r); x.arcTo(rx,ry,rx+w,ry,r); x.closePath(); }\n  function wrapText(x,t,rx,ry,maxw,lh){ var words=t.split(' '),line='',yy=ry; for(var i=0;i<words.length;i++){ var test=line+words[i]+' '; if(x.measureText(test).width>maxw&&i>0){ x.fillText(line,rx,yy); line=words[i]+' '; yy+=lh; } else line=test; } x.fillText(line,rx,yy); }\n  function openStack(){ drawStack(); $('stack').classList.add('open'); accountGate(); }\n  function closeStack(){ $('stack').classList.remove('open'); }\n  $('stackBtn').addEventListener('click', openStack);\n  $('stackClose').addEventListener('click', closeStack);\n  $('stack').addEventListener('click', function(e){ if(e.target===$('stack')) closeStack(); });\n  $('stackDl').addEventListener('click', function(){ var a=document.createElement('a'); a.download='velox-research-stack.png'; a.href=$('stackCanvas').toDataURL('image/png'); a.click(); toast('Stack card downloaded'); });\n  $('stackShare').addEventListener('click', function(){\n    $('stackCanvas').toBlob(function(blob){\n      var file=new File([blob],'velox-research-stack.png',{type:'image/png'});\n      if(navigator.canShare && navigator.canShare({files:[file]})){ navigator.share({files:[file],title:'My Velox research stack',text:'Built with Velox compare'}).catch(function(){}); }\n      else { var a=document.createElement('a'); a.download='velox-research-stack.png'; a.href=URL.createObjectURL(blob); a.click(); toast('Saved — share the image'); }\n    },'image/png');\n  });\n\n  $('acctClose').addEventListener('click', function(){ $('acctNudge').classList.remove('show'); });\n  $('shareBtn').addEventListener('click', function(){ navigator.clipboard && navigator.clipboard.writeText(location.href); toast('Link copied — share your comparison'); });\n  $('resetBtn').addEventListener('click', function(){ ids=['bpc-157','tb-500']; tab='overview'; renderLenses(); renderMatrix(); syncURL(); });\n\n  renderLenses(); renderMatrix(); syncURL();\n})();\n</script>\n</body>\n</html>\n";
